package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.EmployeeTransferRequest; import EmployeeManagementSystem.repository.EmployeeTransferRequestRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class EmployeeTransferRequestServiceImpl implements EmployeeTransferRequestService{
 private final EmployeeTransferRequestRepository repo; public EmployeeTransferRequestServiceImpl(EmployeeTransferRequestRepository r){repo=r;}
 public List<EmployeeTransferRequest> my(String u){return repo.findByUserIdOrderByCreatedAtDesc(u);} public List<EmployeeTransferRequest> all(){return repo.findAllByOrderByCreatedAtDesc();}
 public EmployeeTransferRequest create(EmployeeTransferRequest x,String u,String n){if(x.getTransferType()==null||x.getTransferType().isBlank())throw new IllegalArgumentException("Transfer type is required."); if(x.getRequestedEffectiveDate()==null)throw new IllegalArgumentException("Effective date is required."); if(x.getReason()==null||x.getReason().isBlank())throw new IllegalArgumentException("Reason is required."); if(repo.existsByUserIdAndStatusIn(u,List.of("SUBMITTED","UNDER_REVIEW")))throw new IllegalArgumentException("An active transfer request already exists."); x.setId(null);x.setRequestNumber("TRF-"+System.currentTimeMillis());x.setUserId(u);x.setEmployeeName(n);x.setStatus("SUBMITTED");return repo.save(x);}
 public EmployeeTransferRequest review(Long id,String s,String c,String r){EmployeeTransferRequest x=repo.findById(id).orElseThrow(()->new NoSuchElementException("Transfer request not found."));if(!Set.of("UNDER_REVIEW","APPROVED","REJECTED","CANCELLED").contains(s))throw new IllegalArgumentException("Invalid status.");x.setStatus(s);x.setReviewerUserId(r);x.setReviewerComment(c);x.setReviewedAt(java.time.LocalDateTime.now());return repo.save(x);}
}
